/// A constant value (floats as IEEE-754 bits).
#[derive(Clone, Copy, Debug)]
#[allow(
    dead_code,
    reason = "the value model of PHP constants; not every kind occurs"
)]
pub(super) enum C {
    Null,
    Bool(bool),
    Int(i64),
    Float(u64),
    Str(&'static [u8]),
    Array(&'static [(K, C)]),
}

/// An array key of a [`C::Array`].
#[derive(Clone, Copy, Debug)]
pub(super) enum K {
    Int(i64),
    Str(&'static [u8]),
}

/// The visibility of a constant.
#[derive(Clone, Copy, Debug)]
#[allow(dead_code, reason = "not every visibility occurs")]
pub(super) enum V {
    Public,
    Protected,
    Private,
}

/// What a [`TwigClass`] is.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[allow(dead_code, reason = "not every kind occurs")]
pub(super) enum Kind {
    Class,
    AbstractClass,
    FinalClass,
    Interface,
    Trait,
    Enum,
    IntEnum,
    StringEnum,
}

